I will query the ORCID public API for each identifier and collect the works summaries, including type and publication date. Then we can count items with year < 2020.

Initial retrieval code:
```python
import requests

orcids = [
    '0000-0003-0396-0333',
    '0000-0001-6102-7846',
    '0000-0002-1053-2030',
    '0000-0002-2605-6569',
    '0000-0002-0209-2784'
]

headers = {'Accept': 'application/json'}

all_works = {}
for oid in orcids:
    url = f'https://pub.orcid.org/v3.0/{oid}/works'
    try:
        r = requests.get(url, headers=headers, timeout=15)
        r.raise_for_status()
        works = []
        data = r.json()
        for group in data.get('group', []):
            for w in group.get('work-summary', []):
                pub = w.get('publication-date') or {}
                type_ = w.get('type')
                year = None
                if pub.get('year') and isinstance(pub['year'], dict):
                    year = pub['year'].get('value')
                elif isinstance(pub.get('year'), str):
                    year = pub.get('year')
                works.append({
                    'put-code': w.get('put-code'),
                    'type': type_,
                    'year': int(year) if year and str(year).isdigit() else None,
                    'source': w.get('source')
                })
        all_works[oid] = works
    except Exception as e:
        all_works[oid] = []
        print(f'Fetch error for {oid}: {e}')

# Show a brief summary of counts retrieved
summary = {oid: len(ws) for oid, ws in all_works.items()}
print(summary)
```

To further ensure robustness of the journal-article counts, I'll quickly validate DOI formatting for a sample subset and confirm that our deduplication didn't miss obvious variants (uppercase, URL-wrapped DOIs, etc.). This is a minor sanity check and should not change counts materially.

```python
sample_bad = {}
for oid in pre2020_counts.keys():
    # Re-scan a small subset by refetching first 5 works details and checking DOI regex variations
    checked = 0
    bad = 0
    for w in all_works[oid]:
        if w.get('type') != 'journal-article' or not (isinstance(w.get('year'), int) and w.get('year') < 2020):
            continue
        if checked >= 5:
            break
        put_code = w.get('put-code')
        if put_code is None:
            continue
        try:
            du = f"https://pub.orcid.org/v3.0/{oid}/work/{put_code}"
            rr = requests.get(du, headers={'Accept':'application/json'}, timeout=10)
            rr.raise_for_status()
            dj = rr.json()
            ext_ids = dj.get('external-ids', {}).get('external-id', [])
            doi_vals = [eid.get('external-id-value') or '' for eid in ext_ids if (eid.get('external-id-type') or '').lower() in ('doi','crossref')]
            # lenient regex: allow uppercase and spaces trimmed
            good = any(re.search(r"10\.\d{4,9}/\S+", val.strip(), re.I) for val in doi_vals)
            if not good:
                bad += 1
            checked += 1
        except Exception:
            continue
    sample_bad[oid] = {'checked': checked, 'bad': bad}

print(sample_bad)
```
